mapper.update:
UPDATE dsblty_info
DSBLTY_GRD_CD=#{dsbltyGrdCd}, DSBLTY_RSN=#{reason}, DSBLTY_RSN=#{dsbltyRsn}, DSBLTY_JGMT_CD=#{dsbltyJgmtCd}, PRCS_STTS_CD=#{prcsSttsCd}, LAST_MDFCN_DT=NOW()
WHERE DSBLTY_NO=#{dsbltyNo}

UPDATE dsblty_info
PRCS_STTS_CD=#{prcsSttsCd}, IDNTY_USER_ID=#{idntyUserId},IDNTY_DT=NOW(), DSBLTY_END_DT=COALESCE(DSBLTY_END_DT,NOW()), LAST_MDFCN_DT=NOW()
WHERE DSBLTY_NO=#{dsbltyNo}
